//! Promedio de una columna numérica de un CSV, en streaming y sin dependencias.
//!
//! Soporta comillas RFC 4180 (comas y saltos de línea embebidos, escape `""`),
//! finales de línea CRLF y fila de cabecera opcional. Mantiene un único buffer
//! de registro, así que la memoria es plana sea el archivo de 2 MB o de 20 GB.

use std::borrow::Cow;
use std::fmt;
use std::fs::File;
use std::io::{self, BufRead, BufReader};
use std::path::Path;

#[derive(Debug)]
pub enum CsvError {
    Io(io::Error),
    NoData,
    MissingColumn { record: u64, column: usize },
    InvalidNumber { record: u64, column: usize, value: String },
}

impl fmt::Display for CsvError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            CsvError::Io(e) => write!(f, "error de E/S: {e}"),
            CsvError::NoData => write!(f, "no se encontró ningún valor numérico"),
            CsvError::MissingColumn { record, column } => {
                write!(f, "registro {record}: no existe la columna {column}")
            }
            CsvError::InvalidNumber { record, column, value } => {
                write!(f, "registro {record}: la columna {column} no es numérica: {value:?}")
            }
        }
    }
}

impl std::error::Error for CsvError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            CsvError::Io(e) => Some(e),
            _ => None,
        }
    }
}

impl From<io::Error> for CsvError {
    fn from(e: io::Error) -> Self {
        CsvError::Io(e)
    }
}

